// Shared source/installed-package proof. Inspect actual triangles and materials;
// metadata-only port checks cannot detect a wrongly coloured boundary face.
export function boundaryMaterialProof(core,T,{prepareTileArt,createTileArtProvider},{surfaceRecipe,tileArtBundle,tileArtTransforms},{captureGeometry=false}={}){
 const interior=new T.MeshStandardMaterial({color:0xb02080,vertexColors:true}),shared=new T.MeshStandardMaterial({color:0x20a0a0,vertexColors:true}),faceMaterials=['north','east','south','west'].map((face,i)=>{const m=new T.MeshStandardMaterial({color:[0xd68b28,0x408b3c,0x286ab5,0xc9b52b][i],vertexColors:true});m.name='boundary-'+face;return m;});interior.name='interior-magenta';shared.name='boundary-cyan';const materials=[interior,shared,...faceMaterials],key=p=>p.map(v=>Math.fround(v)).join(','),edgeKey=(a,b)=>[key(a),key(b)].sort().join('|'),cases=[],failures=[];let borrowedDisposals=0,edgesChecked=0,interiorFaces=0,multipleBoundaryFaces=0;
 for(const m of materials)m.addEventListener('dispose',()=>borrowedDisposals++);
 try{for(const distinctProfiles of [false,true])for(const detail of [0,1,2])for(const transform of tileArtTransforms){
  const recipe=surfaceRecipe('material-proof',2,2,{segments:2});if(distinctProfiles)for(const port of recipe.ports){port.profiles.material.id='paint.'+port.faceId;port.boundary.materialIntervals[0].material.id=port.profiles.material.id;}
  const bundle=tileArtBundle(core,[recipe],[{id:'material-proof',recipeId:recipe.id,transform}]),before=JSON.stringify(bundle),projection=prepareTileArt(core,bundle,{detail}),expected=new Map(),portMaterials=new Map(projection.entries[0].inspected.ports.map(p=>[p.id,distinctProfiles?faceMaterials[['north','east','south','west'].indexOf(p.faceId)]:shared]));
  for(const p of projection.entries[0].inspected.ports){const points=p.geometry.positions.map(v=>[v[0]/1e6,v[2]/1e6,v[1]/1e6]);for(let i=1;i<points.length;i++)expected.set(edgeKey(points[i-1],points[i]),{portId:p.id,material:portMaterials.get(p.id),seen:0});}
  const label={distinctProfiles,detail,quarterTurns:transform.quarterTurns,mirrorX:transform.mirrorX},view=createTileArtProvider(T,projection,{materialForInstance:()=>interior,profileBindings:projection.entries[0].inspected.ports.map(p=>({profiles:p.profiles,boundaryMaterial:p.geometry.materialIntervals[0].material,material:portMaterials.get(p.id)}))});let mismatches=0,checked=0;const geometryRecords=[];
  try{for(const group of view.root.children)for(const mesh of group.children){if(mesh.userData.role!=='canonical-surface')continue;const a=mesh.geometry.attributes.position;for(let i=0;i<a.count;i+=3){if(captureGeometry){const attributes=mesh.geometry.attributes;geometryRecords.push([0,1,2].flatMap(j=>['position','normal','uv'].flatMap(name=>Array.from({length:attributes[name].itemSize},(_,k)=>attributes[name].array[(i+j)*attributes[name].itemSize+k]))).join(','));}const points=[0,1,2].map(j=>[a.getX(i+j),a.getY(i+j),a.getZ(i+j)]),borders=points.map((p,j)=>expected.get(edgeKey(p,points[(j+1)%3]))).filter(Boolean);if(borders.length>1)multipleBoundaryFaces++;if(!borders.length){interiorFaces++;if(mesh.material!==interior){mismatches++;if(failures.length<12)failures.push({...label,issue:'interior triangle uses boundary material',actual:mesh.material.name});}}for(const edge of borders){edge.seen++;checked++;edgesChecked++;if(mesh.material!==edge.material){mismatches++;if(failures.length<12)failures.push({...label,issue:'boundary-adjacent triangle uses wrong actual material',portId:edge.portId,expected:edge.material.name,actual:mesh.material.name});}}}}
   for(const e of expected.values())if(e.seen!==1){mismatches++;if(failures.length<12)failures.push({...label,issue:'canonical edge coverage',portId:e.portId,seen:e.seen});}
   if(JSON.stringify(bundle)!==before){mismatches++;failures.push({...label,issue:'authored bundle mutated'});}cases.push({...label,canonicalEdges:expected.size,checked,mismatches,...captureGeometry?{geometryRecords:geometryRecords.sort()}: {}});
  }finally{view.dispose();view.dispose();}
 }
 if(borrowedDisposals)failures.push({issue:'provider disposed borrowed materials',count:borrowedDisposals});
 return {status:cases.length===48&&cases.every(c=>c.checked===8&&c.mismatches===0)&&!borrowedDisposals&&multipleBoundaryFaces>0&&interiorFaces>0?'pass':'fail',cases,edgesChecked,interiorFaces,multipleBoundaryFaces,borrowedDisposals,failures,qualification:'Actual provider mesh/material selection; 2x2 canonical surface, two intervals per side, shared and distinct face profiles, all detail levels and D4 placements.'};
 }finally{for(const m of materials)m.dispose();}
}
